const items = $input.all();

// 1. الرسم الأول: Grouped Bar Chart (مقارنة تفصيلية لحركات المخزون لأول 10 منتجات)
const labels1 = items.map(item => item.json.product_name).slice(0, 10);
const availableQty = items.map(item => item.json.available_qty).slice(0, 10);
const incomingQty = items.map(item => item.json.incoming_qty).slice(0, 10);
const outgoingQty = items.map(item => item.json.outgoing_qty).slice(0, 10);

const chart1 = {
  type: 'bar',
  data: {
    labels: labels1,
    datasets: [
      {
        label: 'المتاح (Available)',
        data: availableQty,
        backgroundColor: 'rgba(54, 162, 235, 0.8)',
        borderColor: 'rgba(54, 162, 235, 1)',
        borderWidth: 1
      },
      {
        label: 'الوارد (Incoming)',
        data: incomingQty,
        backgroundColor: 'rgba(75, 192, 192, 0.8)',
        borderColor: 'rgba(75, 192, 192, 1)',
        borderWidth: 1
      },
      {
        label: 'الصادر (Outgoing)',
        data: outgoingQty,
        backgroundColor: 'rgba(255, 99, 132, 0.8)',
        borderColor: 'rgba(255, 99, 132, 1)',
        borderWidth: 1
      }
    ]
  },
  options: {
    responsive: true,
    plugins: {
      title: {
        display: true,
        text: 'مقارنة حركة المخزون التفصيلية (المتاح، الوارد، الصادر)',
        font: { size: 14 }
      },
      legend: { position: 'bottom' }
    },
    scales: {
      y: { beginAtZero: true, grid: { color: '#e2e8f0' } },
      x: { grid: { display: false } }
    }
  }
};

// 2. الرسم الثاني: Advanced Doughnut Chart (توزيع إجمالي التكلفة مع نسب وقيم واضحة)
const labels2 = items.map(item => item.json.sku).slice(0, 8);
const data2 = items.map(item => item.json.total_cost_value).slice(0, 8);

const chart2 = {
  type: 'doughnut',
  data: {
    labels: labels2,
    datasets: [{
      data: data2,
      backgroundColor: [
        '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#14b8a6', '#6366f1'
      ],
      borderWidth: 2,
      borderColor: '#ffffff'
    }]
  },
  options: {
    responsive: true,
    plugins: {
      title: {
        display: true,
        text: 'توزيع رأس المال المستثمر حسب الـ SKU ($)',
        font: { size: 14 }
      },
      legend: { position: 'right' }
    }
  }
};

// 3. الرسم الثالث: Horizontal Bar Chart (تحليل الأسعار والتكاليف للمنتجات)
const labels3 = items.map(item => item.json.product_name).slice(0, 8);
const unitPrices = items.map(item => item.json.unit_price).slice(0, 8);
const unitCosts = items.map(item => item.json.unit_cost).slice(0, 8);

const chart3 = {
  type: 'horizontalBar',
  data: {
    labels: labels3,
    datasets: [
      {
        label: 'سعر البيع (Unit Price)',
        data: unitPrices,
        backgroundColor: 'rgba(16, 185, 129, 0.7)',
        borderColor: 'rgba(16, 185, 129, 1)',
        borderWidth: 1
      },
      {
        label: 'التكلفة (Unit Cost)',
        data: unitCosts,
        backgroundColor: 'rgba(239, 68, 68, 0.7)',
        borderColor: 'rgba(239, 68, 68, 1)',
        borderWidth: 1
      }
    ]
  },
  options: {
    responsive: true,
    plugins: {
      title: {
        display: true,
        text: 'مقارنة سعر البيع مع تكلفة الوحدة',
        font: { size: 14 }
      },
      legend: { position: 'bottom' }
    },
    scales: {
      x: { beginAtZero: true, grid: { color: '#e2e8f0' } },
      y: { grid: { display: false } }
    }
  }
};

// توليد روابط الـ API بدقة ووضوح (عرض 700 بكسل لطد خروج رسومات واضحة وعالية الدقة)
const chartUrl1 = `https://quickchart.io/chart?w=700&h=350&c=${encodeURIComponent(JSON.stringify(chart1))}`;
const chartUrl2 = `https://quickchart.io/chart?w=700&h=350&c=${encodeURIComponent(JSON.stringify(chart2))}`;
const chartUrl3 = `https://quickchart.io/chart?w=700&h=350&c=${encodeURIComponent(JSON.stringify(chart3))}`;

return [{ json: { chartUrl1, chartUrl2, chartUrl3 } }];
